// Standalone stub for vuex: 提供 MarketHeader 所需的最小 store 接口
// 原组件使用 mapState({ platformConfig }) 与 $store.dispatch('app/getPlatformConfig')
// standalone 场景下无平台配置来源，直接返回空 platformConfig，让 logo 走兜底 lucide 图标。
const VuexStub = {
  install(Vue) {
    const store = {
      state: {
        app: {
          platformConfig: null
        }
      },
      getters: {},
      dispatch() {
        // 无后端：忽略 getPlatformConfig 之类的异步 action
        return Promise.resolve()
      },
      commit() {},
      watch() {},
      subscribe() {},
      replaceState() {}
    }
    Vue.prototype.$store = store
    Vue.store = store
  }
}

export default VuexStub
export const mapState = () => {
  // 兼容对象形式：{ key: state => value }
  return {
    platformConfig(state) {
      return state.app && state.app.platformConfig
    }
  }
}
export const mapGetters = () => ({})
export const mapActions = () => ({})
export const mapMutations = () => ({})
export const createNamespacedHelpers = () => ({ mapState, mapGetters, mapActions, mapMutations })

// Standalone stub: 无后端静态资源前缀，原样返回（不抛错）
export function resolveServerAssetUrl(input) {
  if (input == null || input === '') return ''
  return String(input).trim()
}
export function resolvePublicStaticUrl(input) {
  if (input == null || input === '') return ''
  return String(input).trim()
}
export function resolvePublicAssetUrl(url) {
  if (url == null || url === '') return ''
  return String(url).trim()
}

// Standalone entry for the market-monitor dashboard.
// Mounts the exact same Vue component tree used in the app, so UI is 1:1.
import Vue from 'vue'
import MarketMonitorIndex from '@/views/property/marketMonitor/index.vue'

// 全局样式重置（模拟浏览器默认 -> 面板自带 .mm-dashboard 作用域样式覆盖）
import './base.css'

Vue.config.productionTip = false
Vue.config.devtools = false

// eslint-disable-next-line no-new
new Vue({
  el: '#app',
  render: (h) => h(MarketMonitorIndex)
})

/* Minimal base reset so the standalone page matches the app's body defaults.
   The dashboard's own dashboard.css is scoped under .mm-dashboard and is
   self-sufficient; this only normalizes html/body margins & box model. */
*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Microsoft YaHei', 'PingFang SC', 'Helvetica Neue', Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: #1e293b;
}
#app { width: 100%; }

import { defineConfig } from 'vite'
import vue from 'vite-ng-plugin-vue2'
import path from 'path'

const srcDir = path.resolve(__dirname, '../src')
const buildDir = path.resolve(__dirname)

// Standalone build: bundle the market-monitor dashboard (Vue2 + echarts) into a
// SINGLE self-contained JS + SINGLE CSS file, with NO external references, so it
// can be inlined into one dependency-free HTML.
export default defineConfig({
  root: buildDir,
  plugins: [vue()],
  resolve: {
    alias: [
      // Project-coupled deps -> standalone stubs
      { find: /^vuex$/, replacement: path.resolve(buildDir, 'store-stub.js') },
      { find: /^@\/utils\/resolveServerAssetUrl\.js$/, replacement: path.resolve(buildDir, 'resolveServerAssetUrl-stub.js') },
      { find: /^@\//, replacement: srcDir + '/' }
    ],
    extensions: ['.js', '.vue', '.json', '.scss']
  },
  build: {
    outDir: path.resolve(buildDir, 'output'),
    emptyOutDir: true,
    sourcemap: false,
    minify: 'esbuild',
    target: 'es2015',
    cssCodeSplit: false,
    assetsInlineLimit: 100000000, // inline every asset as base64/data URI
    rollupOptions: {
      input: path.resolve(buildDir, 'entry.js'),
      output: {
        inlineDynamicImports: true,
        format: 'iife',
        entryFileNames: 'app.js',
        chunkFileNames: 'app.js',
        assetFileNames: 'app.[ext]'
      }
    }
  },
  esbuild: {
    drop: []
  }
})

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const outDir = path.resolve(__dirname, 'output')
const js = fs.readFileSync(path.join(outDir, 'app.js'), 'utf8')
const css = fs.readFileSync(path.join(outDir, 'app.css'), 'utf8')

// Escape any closing script/comment sequences so the JS/CSS survive inlining.
function safeScript(s) {
  return s.replace(/<\/script/gi, '<\\/script')
}
function safeStyle(s) {
  return s.replace(/<\/style/gi, '<\\/style')
}

const html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>苏州市房地产市场数据分析平台</title>
<style>
${safeStyle(css)}
</style>
</head>
<body>
<div id="app"></div>
<script>
${safeScript(js)}
</script>
</body>
</html>
`

const outFile = path.resolve(__dirname, 'market-monitor.standalone.html')
fs.writeFileSync(outFile, html, 'utf8')
console.log('[assemble] wrote', outFile, (html.length / 1024 / 1024).toFixed(2) + 'MB')

