const { chromium } = require('playwright')
const path = require('path')

const OUT = 'D:/repository/门户/zhi2-web-admin/standalone-build/shots'

async function shoot(browser, url, file, opts = {}) {
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message))
  const failures = []
  page.on('requestfailed', (r) => failures.push(r.url() + ' :: ' + (r.failure() && r.failure().errorText)))
  await page.goto(url, { waitUntil: 'networkidle', timeout: 45000 })
  await page.waitForTimeout(opts.wait || 2500)
  await page.screenshot({ path: path.join(OUT, file), fullPage: false })
  // size of the dashboard container
  const dims = await page.evaluate(() => {
    const el = document.querySelector('.mm-dashboard')
    if (!el) return null
    const r = el.getBoundingClientRect()
    return { w: Math.round(r.width), h: Math.round(r.height), scrollH: el.scrollHeight }
  })
  await page.close()
  return { file, errors, failures, dims }
}

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const results = {}
  results.standalone = await shoot(browser, 'http://127.0.0.1:8099/', 'standalone-1920x1080.png')
  results.original = await shoot(browser, 'http://127.0.0.1:8092/market-monitor', 'original-1920x1080.png', { wait: 3500 })
  await browser.close()
  console.log(JSON.stringify(results, null, 2))
})().catch((e) => { console.error('FATAL', e); process.exit(1) })

