cd 'D:\repository\门户\zhi2-web-admin\standalone-build'; @'
const { chromium } = require('playwright')
const path = require('path')
const OUT = 'D:/repository/门户/zhi2-web-admin/standalone-build/shots'
;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message))
  await page.goto('http://127.0.0.1:8099/', { waitUntil: 'networkidle' })
  await page.waitForTimeout(1500)

  const report = {}

  // 1) Change district filter -> 姑苏区 (value gu-su? inspect options)
  const districtOpts = await page.$$eval('.mm-dashboard select:nth-of-type(1) option, select option', els => els.map(o => ({v:o.value,t:o.textContent})))
  report.districtOptions = districtOpts.slice(0, 12)

  // There are two selects; district is the second. Use all selects text.
  const selects = await page.$$('.mm-dashboard select')
  report.selectCount = selects.length
  // district select = one containing '监测范围' nearby; just pick the one whose options include 全市
  let districtSel = null
  for (const s of selects) {
    const first = await s.$eval('option', o => o.textContent).catch(()=>'')
    if ((first||'').includes('全市')) { districtSel = s; break }
  }
  if (districtSel) {
    await districtSel.selectOption({ index: 1 }) // pick first district
    await page.waitForTimeout(1200)
    await page.screenshot({ path: path.join(OUT, 'standalone-district-filtered.png') })
    report.districtChanged = await districtSel.$eval('select', s=>s.value).catch(()=>null)
    report.districtOptionsAll = await districtSel.$$eval('option', os=>os.map(o=>o.value))
  }

  // reload to reset
  await page.goto('http://127.0.0.1:8099/', { waitUntil: 'networkidle' })
  await page.waitForTimeout(1200)

  // 2) click panels that open modals: find clickable cards / "查看详情" or arrows
  const clickables = await page.$$eval('.mm-dashboard [class*="cursor-pointer"], .mm-dashboard button', els => els.length)
  report.clickables = clickables

  // Try clicking each KPI card / trade panel / cumulative / buyer panel titles
  const candidates = await page.$$('.mm-dashboard [class*="cursor-pointer"]')
  report.candidateClickCount = candidates.length
  for (let i = 0; i < Math.min(candidates.length, 8); i++) {
    try {
      await candidates[i].click({ timeout: 1500 })
      await page.waitForTimeout(800)
      const modalOpen = await page.evaluate(() => {
        const fixed = document.querySelectorAll('.mm-dashboard .fixed')
        return fixed.length
      })
      if (modalOpen > 0) {
        report.modalAfterClickIndex = i
        await page.screenshot({ path: path.join(OUT, 'standalone-modal-' + i + '.png') })
        // close via ESC or click close
        await page.keyboard.press('Escape').catch(()=>{})
        const closeBtn = await page.$('.mm-dashboard .fixed [class*="close"], .mm-dashboard .fixed button')
        if (closeBtn) await closeBtn.click({ timeout: 1000 }).catch(()=>{})
        await page.waitForTimeout(500)
      }
    } catch (e) {}
  }

  report.errors = errors
  console.log(JSON.stringify(report, null, 2))
  await browser.close()
})().catch(e => { console.error('FATAL', e); process.exit(1) })
